use std::process;

const DEFAULT_COUNT: i32 = 15;

pub fn parse_count<I>(args: I) -> i32
where
    I: IntoIterator<Item = String>,
{
    let args: Vec<String> = args.into_iter().collect();
    let mut count = DEFAULT_COUNT;

    if args.len() > 1 && args[1] == "--a" {
        let value = match args.get(2) {
            Some(value) => value,
            None => abort_logic_error(),
        };
        count = stoi_i32(value);
    }

    count
}

fn stoi_i32(input: &str) -> i32 {
    let bytes = input.as_bytes();
    let mut index = 0usize;

    while index < bytes.len() && is_ascii_space(bytes[index]) {
        index += 1;
    }

    let mut sign = 1i64;
    if index < bytes.len() {
        match bytes[index] {
            b'+' => index += 1,
            b'-' => {
                sign = -1;
                index += 1;
            }
            _ => {}
        }
    }

    let digits_start = index;
    let mut value = 0i64;
    while index < bytes.len() {
        let byte = bytes[index];
        if !byte.is_ascii_digit() {
            break;
        }

        value = match value
            .checked_mul(10)
            .and_then(|current| current.checked_add(i64::from(byte - b'0')))
        {
            Some(value) => value,
            None => abort_out_of_range(),
        };

        index += 1;
    }

    if index == digits_start {
        abort_invalid_argument();
    }

    let signed_value = match value.checked_mul(sign) {
        Some(value) => value,
        None => abort_out_of_range(),
    };

    if signed_value < i64::from(i32::MIN) || signed_value > i64::from(i32::MAX) {
        abort_out_of_range();
    }

    signed_value as i32
}

fn is_ascii_space(byte: u8) -> bool {
    matches!(byte, b' ' | b'\n' | b'\r' | b'\t' | 0x0B | 0x0C)
}

fn abort_invalid_argument() -> ! {
    eprintln!("terminate called after throwing an instance of 'std::invalid_argument'");
    eprintln!("  what():  stoi");
    process::abort();
}

fn abort_out_of_range() -> ! {
    eprintln!("terminate called after throwing an instance of 'std::out_of_range'");
    eprintln!("  what():  stoi");
    process::abort();
}

fn abort_logic_error() -> ! {
    eprintln!("terminate called after throwing an instance of 'std::logic_error'");
    eprintln!("  what():  basic_string::_S_construct null not valid");
    process::abort();
}

