use std::collections::HashMap;
use std::hash::Hash;

pub struct HopscotchMap<K, V> {
    entries: HashMap<K, V>,
}

impl<K, V> HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    pub fn new() -> Self {
        Self {
            entries: HashMap::new(),
        }
    }

    pub fn insert(&mut self, key: K, value: V) -> Option<V> {
        self.entries.insert(key, value)
    }

    pub fn equal_range(&self, key: K) -> EqualRange<'_, K, V> {
        EqualRange {
            entry: self.entries.get_key_value(&key),
        }
    }
}

pub struct EqualRange<'a, K, V> {
    entry: Option<(&'a K, &'a V)>,
}

impl<'a, K, V> Iterator for EqualRange<'a, K, V> {
    type Item = (&'a K, &'a V);

    fn next(&mut self) -> Option<Self::Item> {
        self.entry.take()
    }
}

